/*
 * A382703  Numbers k which appear "prematurely" in A064413, that is, k
 *          appears before the k-th term.
 * https://oeis.org/A382703
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A064413(m) for the n-th index m with A064413(m) > m (EKG
 *            sequence generated by a sieve/search)
 * Range:     u8 n <= 133, u16 n <= 9296, u32 n <= 9296, u64 n <= 9296,
 *            u128 n <= 9296, big any n
 * Validated: standard, pass, 96 terms through n = 8873 (2026-11-10)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define A382703_LIM 1048576u
#define A382703_FCAP 400000u

static uint32_t *A382703_spf = NULL;
static unsigned char *A382703_used = NULL;
static uint32_t *A382703_nxt = NULL;
static uint32_t *A382703_found = NULL;
static size_t A382703_nfound = 0;
static uint32_t A382703_idx = 0, A382703_last = 0;

static void A382703_init(void)
{
    if (A382703_spf) return;
    A382703_spf = (uint32_t *)calloc(A382703_LIM + 1, sizeof(uint32_t));
    A382703_used = (unsigned char *)calloc(A382703_LIM + 1, 1);
    A382703_nxt = (uint32_t *)calloc(A382703_LIM + 1, sizeof(uint32_t));
    A382703_found = (uint32_t *)calloc(A382703_FCAP, sizeof(uint32_t));
    if (!A382703_spf || !A382703_used || !A382703_nxt || !A382703_found) exit(1);
    for (uint32_t i = 2; i <= A382703_LIM; i++) {
        if (A382703_spf[i] == 0) {
            for (uint32_t j = i; j <= A382703_LIM; j += i)
                if (A382703_spf[j] == 0) A382703_spf[j] = i;
        }
    }
    for (uint32_t i = 2; i <= A382703_LIM; i++)
        if (A382703_spf[i] == i) A382703_nxt[i] = i;
    A382703_used[1] = 1;
    A382703_used[2] = 1;
    A382703_idx = 2;
    A382703_last = 2;
}

static void A382703_step(void)
{
    uint32_t x = A382703_last;
    uint32_t best = 0xFFFFFFFFu;
    while (x > 1) {
        uint32_t p = A382703_spf[x];
        while (x % p == 0) x /= p;
        uint32_t c = A382703_nxt[p];
        while (c <= A382703_LIM && A382703_used[c]) c += p;
        A382703_nxt[p] = c;
        if (c < best) best = c;
    }
    if (best > A382703_LIM) exit(1);
    A382703_used[best] = 1;
    A382703_idx++;
    A382703_last = best;
    if (best > A382703_idx && A382703_nfound < A382703_FCAP)
        A382703_found[A382703_nfound++] = best;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;
    A382703_init();
    while ((size_t)n > A382703_nfound) A382703_step();
    return (seq_t)A382703_found[n - 1];
}
